 Certainly! Here's a JavaScript function that uses regular expressions and string manipulation to switch the order of adjectives in a sentence:

```javascript
function switchAdjectiveOrder(sentence) {
  // Define a regex pattern to match adjectives and their preceding articles
  const adjectivePattern = /(([A-Z]\.|[A-Z][a-z]+[^\s]*\.?)[\s,](?:a|an|the)[-\s]*(?:[A-Z][a-z]+[^\s]*[^\s,.]|$))/g;

  let matches = [];
  let currentMatch = null;

  // Find all matches of the pattern in the sentence
  while ((currentMatch = adjectivePattern.exec(sentence)) !== null) {
    matches.push(currentMatch[0]);
  }

  // Reverse the order of the adjectives in the matches array
  matches = matches.slice().reverse();

  // Create an empty string to store the modified sentence
  let result = '';

  // Iterate through each match and insert it back into the sentence with the new order
  for (let i = 0; i < matches.length; i++) {
    result += matches[i];

    // If there's another match before this one, add a comma and a space
    if (i < matches.length - 1) {
      result += ', ';
    }
  }

  // Add the remaining part of the original sentence after the last adjective
  result += sentence.substring(sentence.lastIndexOf(' ') + 1);

  return result;
}

// Test the function with your example sentence
const sentence = 'Beautiful green trees are in the park';
console.log(switchAdjectiveOrder(sentence)); // Output: 'Green beautiful trees are in the park'
```

