function determineProtocol(inputData) {
  let ipVersion = checkIPv6(inputData.sourceIP, inputData.destinationIP);
  if (ipVersion === 6) {
    // IPv6 communication uses various transport protocols, but for this specific example with port 80, we assume HTTP over TCP
    if (inputData.port === 80) {
      return "HTTP";
    } else {
      // For other ports, it could be UDP or another transport protocol, but HTTP is not an option, so we default to UDP
      return "UDP";
    }
  } else {
    // IPv4 is an older version and less likely, but still possible, so we can't exclude it entirely
    if (inputData.port === 80) {
      return "HTTP";
    } else {
      return "UDP";
    }
  }

  function checkIPv6(ip1, ip2) {
    const regexIpv6 = /^(([0-9a-f]{1,4}:){7}[0-9a-f]{1,4}|::(:[0-9a-f]{1,4}){1,8}|([0-9a-f]{1,4}:){1,7}:)|::)$/i;
    return regexIpv6.test(ip1) && regexIpv6.test(ip2) ? 6 : 4;
  }
}
