```c
#include <stdio.h>
#include <stdlib.h> // For malloc() and realloc()
#include <string.h> // For strlen() and strcat()

int main(int argc, char *argv[]) {
    size_t total_length = 0;
    size_t current_arg_length = 0;
    char *combined_str = NULL;

    if (argc == 1) {
        printf("No arguments provided.\n");
        return EXIT_FAILURE;
    }

    // Calculate the total length of the combined string
    for (size_t i = 0; i < argc; ++i) {
        current_arg_length = strlen(argv[i]) + 1; // +1 for space between args and null terminator
        total_length += current_arg_length;
    }

    // Allocate memory for the combined string
    combined_str = malloc(total_length);
    if (!combined_str) {
        perror("malloc: Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    // Concatenate all arguments into the combined string
    for (size_t i = 0; i < argc - 1; ++i) {
        strcat(combined_str, argv[i]);
        strcat(combined_str, " ");
    }
    strcat(combined_str, argv[argc - 1]);

    // Print or use the combined string as needed
    printf("Combined string: %s\n", combined_str);

    // Free allocated memory when done
    free(combined_str);

    return EXIT_SUCCESS;
}
```

