 Here's the code you can use to create `RedisClient` class in your `utils/redis.js` file:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) return reject(err);
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This code defines the `RedisClient` class with the required methods, uses the `redis` package to establish a connection and handles errors. After defining the class, it creates an instance of the class and exports it for use in other parts of your application.

